args.command:
python3 - <<'PY'
import os
terms=('nats','rabbitmq','rabbit','webhook','queue')
for root, dirs, files in os.walk('.'):
    dirs[:]=[d for d in dirs if d not in {'.git','node_modules'}]
    for f in files:
        p=os.path.join(root,f)
        try:
            with open(p,encoding='utf-8') as h:
                for i,line in enumerate(h,1):
                    if any(t in line.lower() for t in terms): print(f'{p}:{i}:{line.rstrip()}')
        except (UnicodeDecodeError,PermissionError): pass
PY

